const data = $input.first().json;
const list = Array.isArray(data.botones_list) ? data.botones_list : [];

const buttons = list.slice(0, 3).map(b => ({
  type: 'reply',
  reply: {
    id: String(b.id || b.title || '').slice(0, 256),
    title: String(b.title || '').slice(0, 20)
  }
}));

const to = $('Entrada').first().json.from;
const bodyText = (data.botones_body || data.output || '¿Qué quieres hacer?').slice(0, 1024);

const payload = {
  messaging_product: 'whatsapp',
  to: to,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: bodyText },
    action: { buttons: buttons }
  }
};

return [{ json: { ...data, wa_payload: payload } }];

// Nodo canonico de entrada: normaliza WhatsApp y n8n Chat a una sola forma.
// Detecta canal por la forma del input (no por refs cruzadas).
const all = $input.first().json;

if (Array.isArray(all.messages) && all.messages.length) {
  const msg = all.messages[0] || {};
  const botonReply = (msg.interactive && (msg.interactive.button_reply || msg.interactive.list_reply)) || null;
  const text = (botonReply && botonReply.title) || (msg.text && msg.text.body) || (msg.image && msg.image.caption) || '';
  return [{ json: {
    canal: 'whatsapp',
    from: msg.from || '',
    phone_number_id: (all.metadata && all.metadata.phone_number_id) || '',
    company_number: (all.metadata && all.metadata.display_phone_number) || '',
    message_id: msg.id || '',
    text: text,
    boton_id: (botonReply && botonReply.id) || '',
    msg_type: msg.type || 'text',
    image_url: (msg.image && msg.image.url) || '',
    image_id: (msg.image && msg.image.id) || '',
    audio_url: (msg.audio && msg.audio.url) || (msg.voice && msg.voice.url) || '',
    audio_id: (msg.audio && msg.audio.id) || (msg.voice && msg.voice.id) || ''
  }}];
}

// n8n Chat: el Chat Trigger expone chatInput y sessionId.
const text = all.chatInput || all.message || all.text || '';
const sid = all.sessionId || all.session_id || all.sessionKey || '';
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : '';
return [{ json: {
  canal: 'chat',
  from: String(sid),
  message_id: 'chat-' + (String(sid) || 'anon') + (execId ? '-' + execId : ''),
  text: String(text),
  boton_id: '',
  msg_type: 'text',
  image_url: '',
  image_id: '',
  audio_url: '',
  audio_id: ''
}}];

// Render para n8n Chat. Texto y flags vienen de Restaurar Output (siempre ejecutado);
// la url del carrito viene de Generar Link Chat (rama true) o del fallback del Filtro.
const r = $('Restaurar Output').first().json;
const parts = [];
const out = (r.output || '').trim();
if (out) parts.push(out);

if (r.es_botones && Array.isArray(r.botones_list) && r.botones_list.length) {
  if (r.botones_body) parts.push((r.botones_body || '').trim());
  parts.push(r.botones_list.map((b, i) => (i + 1) + '. ' + (b.title || '')).join('\n'));
}

const cartUrl = ($json && $json.url) || r.cart_link_url || '';
if (r.es_cart_link) {
  if (cartUrl) parts.push('Abre tu catalogo aqui: ' + cartUrl);
  else parts.push('Ahorita no pude generar tu link del catalogo. Intenta de nuevo en un momento, por favor.');
}

if (r.es_imagen && r.imagen_send_url) parts.push(r.imagen_send_url);
if (r.es_plantilla && r.template_nombre) parts.push('[Plantilla: ' + r.template_nombre + ']');

return [{ json: { output: parts.join('\n\n').trim() } }];

const r = $json || {};
const msg = r.mensaje_bloqueo || 'Por el momento tu codigo de cliente no esta habilitado para hacer pedidos por este medio.';
return [{ json: { output: msg } }];

const base = $('Restaurar Output').first().json;
const entrada = $('Entrada').first().json;
const lista = Array.isArray(base.productos_list) ? base.productos_list : [];
const placeholder = 'https://i.ibb.co/BKwvb5b5/Whats-App-Image-2026-06-05-at-16-31-52.jpg';
const items = lista.map(p => {
  const url = p.img ? ('https://data.dev.pdctechco.com/Fotos/FFA/' + p.sku + '.jpg') : placeholder;
  let caption = '*' + (p.nombre || '') + '*';
  if (p.precio) caption += '\nQ' + p.precio;
  if (p.promo) caption += '\n' + p.promo;
  caption += '\n\nDime cuantas quieres para agregarlo.';
  return { json: { to: entrada.from, phone_number_id: entrada.phone_number_id, image_url: url, caption } };
});
return items.length ? items : [{ json: { skip: true } }];
